 971→/// Derive a short repo name from a directory path.
 972→/// "/Users/jeevan/code/lightfast" → "lightfast"
 973→fn derive_repo_name(path: &std::path::Path) -> String {
 974→    path.file_name()
 975→        .and_then(|n| n.to_str())
 976→        .unwrap_or("repo")
 977→        .to_string()
 978→}
