            std::env::set_var("TMUX", "");
            assert!(!backend.is_inside());

            // When TMUX is unset, we're not inside tmux
            std::env::remove_var("TMUX");
            assert!(!backend.is_inside());

            // Restore original value
            match original {
                Some(v) => std::env::set_var("TMUX", v),
                None => std::env::remove_var("TMUX"),
            }
        }
    }

